          "basis": "source_assertion",
          "citations": [
            {
              "quote": "Active: Ambessa slashes with her twin drakehounds in the target direction, dealing physical damage to enemies hit. The damage is increased against enemies hit by the outer edge.",
              "source_id": "wiki:cunningsweep"
            }
          ],
          "claim": "Cunning Sweep is a directional slash that deals physical damage, increased at its outer edge."
        },
        {
          "basis": "source_assertion",
