      "counterplay": "Sidestep the line and avoid being its first target.",
      "facts": [
        {
          "basis": "source_assertion",
          "citations": [
            {
              "quote": "If this hits at least one enemy, Ambessa can cast Sundering Slam within the next few seconds.",
              "source_id": "wiki:cunningsweep"
            }
          ],
          "claim": "After Cunning Sweep hits an enemy, Ambessa can briefly cast Sundering Slam."
        },
        {
          "basis": "source_assertion",
          "citations": [
            {
              "quote": "Active: Ambessa slams her twin drakehounds in a line in the target direction, dealing physical damage to enemies hit. The damage is increased against the first enemy.",
              "source_id": "wiki:sunderingslam"
            }
          ],
          "claim": "This follow-up deals physical damage in a line, with increased damage to the first enemy hit."
        }
      ],
      "priority": "B",
      "priority_reason": "First-target positioning changes the follow-up's threat.",
      "uncertainties": []
